from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    row_modes = [Counter(row).most_common(1)[0][0] for row in grid]
    col_modes = [Counter(grid[r][c] for r in range(h)).most_common(1)[0][0]
                 for c in range(w)]
    row_counts, col_counts = Counter(row_modes), Counter(col_modes)
    shared = set(row_counts) & set(col_counts)
    # The lattice line color is the shared modal color occurring on fewer
    # rows/columns than the interior tile color.
    line_color = min(shared, key=lambda color: row_counts[color] + col_counts[color])
    rows = [r for r, color in enumerate(row_modes) if color == line_color]
    cols = [c for c, color in enumerate(col_modes) if color == line_color]
    if len(rows) < 2 or len(cols) < 2:
        raise ValueError('Could not identify lattice rows and columns')

    # The most frequent non-line color is the repeating tile background.
    background = Counter(v for row in grid for v in row if v != line_color).most_common(1)[0][0]
    marked = [(ri, ci) for ri, r in enumerate(rows) for ci, c in enumerate(cols)
              if grid[r][c] != line_color and grid[r][c] != background]
    if not marked:
        raise ValueError('No colored markers at lattice intersections')
    rmin = min(ri for ri, _ in marked)
    rmax = max(ri for ri, _ in marked)
    cmin = min(ci for _, ci in marked)
    cmax = max(ci for _, ci in marked)

    out = []
    for ri in range(rmin, rmax):
        out_row = []
        for ci in range(cmin, cmax):
            corners = [grid[rows[r]][cols[c]]
                       for r, c in ((ri, ci), (ri, ci + 1),
                                    (ri + 1, ci), (ri + 1, ci + 1))]
            color = corners[0]
            out_row.append(color if color != line_color and color != background and all(v == color for v in corners) else background)
        out.append(out_row)
    return out


